function symptom(msg) { console.error("FAIL: " + msg); process.exit(1); }
function broken(msg) { console.error("ERROR: " + msg); process.exit(2); }
let z;
try { z = require("zod"); } catch (e) { broken("cannot load zod: " + e.message); }
if (typeof z.toJSONSchema !== "function") broken("z.toJSONSchema is not a function");
const inner = z.string().meta({ id: "Inner" });
const out = z.toJSONSchema(z.object({ a: inner, b: inner }));
const def = out && out.$defs && out.$defs.Inner;
if (!def || def.type !== "string") broken("no $defs.Inner string entry: " + JSON.stringify(out));
if ("id" in def) symptom("toJSONSchema keeps the meta id inside the $defs entry");
console.log("OK: toJSONSchema $defs entry has no id: " + JSON.stringify(def));

